70: function ensureAudio() {
71:   if (!state.sound) return null;
72:   if (!state.audio) {
73:     const AC = window.AudioContext || window.webkitAudioContext;
74:     if (!AC) return null;
75:     state.audio = new AC();
76:   }
77:   if (state.audio.state === 'suspended') state.audio.resume();
78:   return state.audio;
79: }
80: function tone(freq, duration = .08, type = 'sine', vol = .035, slideTo = null) {
81:   const ac = ensureAudio();
82:   if (!ac) return;
83:   const o = ac.createOscillator();
84:   const g = ac.createGain();
85:   o.type = type;
86:   o.frequency.setValueAtTime(freq, ac.currentTime);
87:   if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(30, slideTo), ac.currentTime + duration);
88:   g.gain.setValueAtTime(.0001, ac.currentTime);
89:   g.gain.exponentialRampToValueAtTime(vol, ac.currentTime + .012);
90:   g.gain.exponentialRampToValueAtTime(.0001, ac.currentTime + duration);
91:   o.connect(g); g.connect(ac.destination);
92:   o.start(); o.stop(ac.currentTime + duration + .02);
93: }
