129: function setupAmbient() {
130:   const canvas = $('#ambient');
131:   if (!canvas) return;
132:   const ctx = canvas.getContext('2d');
133:   let w = 0, h = 0, dpr = 1;
134:   const parts = [];
135:   function resize() {
136:     dpr = Math.min(2, window.devicePixelRatio || 1);
137:     w = canvas.width = Math.floor(innerWidth * dpr);
138:     h = canvas.height = Math.floor(innerHeight * dpr);
139:     canvas.style.width = innerWidth + 'px';
140:     canvas.style.height = innerHeight + 'px';
141:   }
142:   function make() {
143:     parts.length = 0;
144:     const count = Math.max(26, Math.min(70, Math.floor(innerWidth / 24)));
145:     for (let i = 0; i < count; i++) {
146:       parts.push({
147:         x: Math.random() * w, y: Math.random() * h,
148:         r: rand(.7, 2.1) * dpr, vx: rand(-.07, .07) * dpr, vy: rand(-.16, -.03) * dpr,
149:         a: rand(.12, .6), p: rand(0, Math.PI * 2), sp: rand(.005, .02)
150:       });
151:     }
152:   }
153:   resize(); make();
154:   addEventListener('resize', () => { resize(); make(); });
155:   let last = performance.now();
156:   function frame(t) {
157:     const dt = Math.min(2, (t - last) / 16.67); last = t;
158:     ctx.clearRect(0, 0, w, h);
159:     for (const p of parts) {
160:       p.x += p.vx * dt; p.y += p.vy * dt; p.p += p.sp * dt;
161:       if (p.y < -10) { p.y = h + 10; p.x = Math.random() * w; }
162:       if (p.x < -10) p.x = w + 10;
163:       if (p.x > w + 10) p.x = -10;
164:       const alpha = p.a * (0.55 + 0.45 * Math.sin(p.p));
165:       const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r * 6);
166:       g.addColorStop(0, `rgba(240,219,151,${alpha})`);
167:       g.addColorStop(.35, `rgba(190,220,160,${alpha * .35})`);
168:       g.addColorStop(1, 'rgba(190,220,160,0)');
169:       ctx.fillStyle = g;
170:       ctx.beginPath(); ctx.arc(p.x, p.y, p.r * 6, 0, Math.PI * 2); ctx.fill();
171:       ctx.fillStyle = `rgba(255,244,195,${alpha})`;
172:       ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2); ctx.fill();
173:     }
174:     requestAnimationFrame(frame);
175:   }
176:   if (!state.reduced) requestAnimationFrame(frame);
177: }
