418: function availableNodes() {
419:   const run = state.run;
420:   if (!run) return [];
421:   const cur = NODE_BY_ID[run.current] || NODE_BY_ID.start;
422:   const next = MAP_NODES.filter(n => n.row === cur.row + 1 && Math.abs(n.col - cur.col) <= 1);
423:   return next.filter(n => !run.visited.includes(n.id));
