425: function renderMap() {
426:   const run = state.run;
427:   if (!run) return;
428:   const nodesEl = $('#map-nodes');
429:   const svg = $('#map-lines');
430:   if (!nodesEl || !svg) return;
431:   const pos = (n) => ({ x: 18 + n.col * 32, y: 94 - n.row * 8.15 });
432:   const avail = new Set(availableNodes().map(n => n.id));
433:   const pathSet = new Set(run.path || run.visited);
434:   const cur = NODE_BY_ID[run.current] || NODE_BY_ID.start;
435: 
436:   let svgHtml = '';
437:   for (const [a, b] of MAP_EDGES) {
438:     const na = NODE_BY_ID[a], nb = NODE_BY_ID[b];
439:     const pa = pos(na), pb = pos(nb);
440:     const d = `M ${pa.x} ${pa.y} C ${pa.x} ${pa.y - 3.2}, ${pb.x} ${pb.y + 3.2}, ${pb.x} ${pb.y}`;
441:     let cls = '';
442:     if (pathSet.has(a) && pathSet.has(b)) cls = 'route';
443:     else if (a === cur.id && avail.has(b)) cls = 'available';
444:     svgHtml += `<path class="${cls}" d="${d}"/>`;
445:   }
446:   svg.innerHTML = svgHtml;
447: 
448:   nodesEl.innerHTML = MAP_NODES.map(n => {
449:     const p = pos(n);
450:     const meta = NODE_META[n.type] || NODE_META.wild;
451:     const visited = run.visited.includes(n.id);
452:     const isCurrent = run.current === n.id;
453:     const isAvailable = avail.has(n.id);
454:     const cls = ['map-node', `type-${n.type}`,
455:       visited ? 'visited' : '', isCurrent ? 'current' : '',
456:       isAvailable ? 'available' : (!visited && !isCurrent ? 'locked' : '')
457:     ].filter(Boolean).join(' ');
458:     const badge = isCurrent ? '<span class="node-badge">✦</span>' : '';
459:     return `<button class="${cls}" style="left:${p.x}%;top:${p.y}%" data-node="${n.id}"
460:       data-tip="<b>${meta.label}</b>${meta.desc}" aria-label="${meta.label}">
461:       ${icon(meta.icon)}${n.row > 0 ? `<span class="node-floor">${n.row + 1}</span>` : ''}${badge}
462:     </button>`;
463:   }).join('');
464: 
465:   $$('.map-node.available', nodesEl).forEach(btn => btn.addEventListener('click', () => {
