601: function chooseEnemySpecies(node) {
602:   const run = state.run;
603:   if (node.type === 'boss') return 'mewtwo';
604:   if (node.type === 'elite') {
605:     const pool = ELITE_POOL.filter(k => k !== run.lastElite);
606:     const key = pick(pool.length ? pool : ELITE_POOL);
607:     run.lastElite = key;
608:     return key;
609:   }
610:   if (node.type === 'grass' && Math.random() < .065) return 'mew';
611:   const tier = node.row <= 2 ? 1 : node.row <= 4 ? 2 : node.row <= 7 ? 3 : 4;
612:   const pool = (TIER_POOLS[tier] || TIER_POOLS[3]).filter(k => k !== run.lastWild);
613:   const key = pick(pool.length ? pool : TIER_POOLS[tier]);
614:   run.lastWild = key;
615:   return key;
616: }
