750: function getEnemyIntent(b) {
751:   const sp = SPECIES[b.enemy.key];
752:   const idx = sp.pattern[b.enemy.moveIndex % sp.pattern.length];
753:   return { ...sp.moves[idx], index: b.enemy.moveIndex };
754: }
755: function calcEnemyHit(b, move) {
756:   let d = (move.dmg || 0) + b.enemy.strength;
757:   if (b.enemy.statuses.weak > 0) d = Math.floor(d * .75);
758:   if (b.player.statuses.vulnerable > 0) d = Math.floor(d * 1.5);
759:   return Math.max(0, d);
760: }
761: function renderIntent() {
762:   const b = state.battle;
763:   const move = b.enemy.intent;
764:   if (!move) return;
765:   const card = $('#enemy-intent');
766:   const iconEl = $('#intent-icon');
767:   const copy = $('#intent-value');
768:   let kind = move.kind || 'attack';
769:   let iconName = 'sword';
770:   let value = '';
771:   let label = 'Attack';
772:   if (kind === 'attack') {
773:     const per = calcEnemyHit(b, move);
774:     value = (move.hits || 1) > 1 ? `${per}×${move.hits}` : String(per);
775:     label = 'Attack';
776:   } else if (kind === 'defend') {
777:     iconName = 'shield'; value = String(move.block || 0); label = 'Defend';
778:   } else if (kind === 'buff') {
779:     iconName = 'arrowUp'; value = move.strength ? `+${move.strength}` : `+${move.block || 0}`; label = 'Power up';
780:   } else if (kind === 'debuff') {
781:     iconName = 'arrowDown'; value = String(Math.max(...Object.values(move.playerStatus || { weak: 1 }))); label = 'Hex';
782:   } else if (kind === 'heal') {
783:     iconName = 'heal'; value = `+${move.heal || 0}`; label = 'Recover';
784:   }
785:   card.className = 'intent-card ' + kind;
786:   iconEl.innerHTML = icon(iconName);
787:   copy.textContent = value;
788:   copy.closest('.intent-copy').querySelector('span').textContent = label;
789:   let nameEl = card.querySelector('.intent-name');
790:   if (!nameEl) {
791:     nameEl = document.createElement('span');
792:     nameEl.className = 'intent-name';
793:     card.querySelector('.intent-copy').appendChild(nameEl);
794:   }
795:   nameEl.textContent = move.name;
796:   card.dataset.tip = `<b>${move.name}</b>${intentTip(move)}`;
797: }
