799: function intentTip(move) {
800:   const bits = [];
801:   if (move.dmg) bits.push(`Deals ${move.dmg}${move.hits > 1 ? `×${move.hits}` : ''} damage.`);
802:   if (move.block) bits.push(`Gains ${move.block} Block.`);
803:   if (move.strength) bits.push(`Gains ${move.strength} Strength.`);
804:   if (move.heal) bits.push(`Heals ${move.heal} HP.`);
805:   if (move.playerStatus) bits.push('Applies ' + Object.entries(move.playerStatus).map(([k, v]) => `${v} ${k}`).join(', ') + '.');
806:   if (move.stealGold) bits.push(`Steals ${move.stealGold} gold.`);
807:   if (move.selfDamage) bits.push(`Hurts itself for ${move.selfDamage}.`);
808:   return bits.join(' ');
809: }
