834: function ballChance(type) {
835:   const b = state.battle;
836:   if (!b) return 0;
837:   if (type === 'master') return 100;
838:   const e = b.enemy;
839:   let c = 5 + (1 - e.hp / e.maxHp) * 72 + BALLS[type].bonus + b.catchBonus;
840:   if (hasRelic('lucky_egg')) c += 12;
841:   if (e.statuses.poison > 0) c += 4;
842:   if (e.statuses.burn > 0) c += 2;
843:   if (e.key === 'mew') c += 12;
844:   if (e.isBoss) c = e.hp / e.maxHp < .25 ? Math.min(c, 52) : Math.min(c, 6);
845:   else if (e.isElite) c = Math.min(c, 78);
846:   return Math.round(clamp(c, 2, 96));
847: }
848: function bestCatchChance() {
849:   if (!state.battle) return 0;
850:   let best = 0;
851:   for (const t of ['poke', 'great', 'ultra', 'master']) {
852:     if ((state.run.balls[t] || 0) > 0) best = Math.max(best, ballChance(t));
853:   }
854:   return best;
855: }
