892: function renderHand() {
893:   const b = state.battle;
894:   const handEl = $('#hand');
895:   if (!b || !handEl) return;
896:   handEl.innerHTML = '';
897:   if (!b.hand.length) {
898:     handEl.innerHTML = '<div style="font-size:10px;letter-spacing:.08em;color:var(--muted-2);padding:18px 0">No cards in hand — end your turn.</div>';
899:     return;
900:   }
901:   for (const card of b.hand) {
902:     const stats = getStats(card.id, card.upgraded);
903:     const el = makeCardEl(card, {
904:       disabled: b.busy || b.over || stats.cost > b.player.energy,
905:       onClick: (c) => playCard(c.uid)
906:     });
907:     handEl.appendChild(el);
908:   }
909:   const count = b.hand.length;
910:   const cardW = innerWidth <= 760 ? 106 : (innerHeight <= 680 ? 124 : 138);
911:   const gap = 6;
912:   const needed = count * cardW + Math.max(0, count - 1) * gap;
913:   const avail = Math.max(200, handEl.clientWidth - 10);
914:   const overlap = needed > avail ? -(needed - avail) / Math.max(1, count - 1) : 0;
915:   handEl.style.setProperty('--overlap', overlap.toFixed(1) + 'px');
916: }
