918: async function playCard(uid) {
919:   const b = state.battle;
920:   if (!b || b.busy || b.over) return;
921:   const idx = b.hand.findIndex(c => c.uid === uid);
922:   if (idx < 0) return;
923:   const card = b.hand[idx];
924:   const stats = getStats(card.id, card.upgraded);
925:   if (stats.cost > b.player.energy) {
926:     toast('Not enough energy.', 'bad', 1400); sfx('error');
927:     return;
928:   }
929:   const el = $(`#hand .card[data-uid="${uid}"]`);
