1500: async function animateBall(type, btn) {
1501:   if (state.reduced) return null;
1502:   const layer = $('#fx-layer');
1503:   const target = $('#enemy-mon');
1504:   if (!layer || !target || !btn) return null;
1505:   const lr = layer.getBoundingClientRect();
1506:   const br = btn.getBoundingClientRect();
1507:   const tr = target.getBoundingClientRect();
1508:   const startX = br.left - lr.left + br.width / 2;
1509:   const startY = br.top - lr.top + br.height / 2;
1510:   const endX = tr.left - lr.left + tr.width / 2;
1511:   const endY = tr.top - lr.top + tr.height * .45;
1512:   const el = document.createElement('div');
1513:   el.className = 'ball-projectile ' + (BALLS[type].cls || '');
1514:   el.style.left = startX + 'px';
1515:   el.style.top = startY + 'px';
1516:   el.style.transform = 'translate(-50%,-50%)';
1517:   layer.appendChild(el);
1518:   const anim = el.animate([
1519:     { left: startX + 'px', top: startY + 'px', transform: 'translate(-50%,-50%) scale(.8) rotate(0deg)' },
1520:     { left: (startX + endX) / 2 + 'px', top: Math.min(startY, endY) - 70 + 'px', transform: 'translate(-50%,-50%) scale(1.1) rotate(220deg)', offset: .55 },
1521:     { left: endX + 'px', top: endY + 'px', transform: 'translate(-50%,-50%) scale(1) rotate(360deg)' }
1522:   ], { duration: 560, easing: 'cubic-bezier(.2,.8,.2,1)' });
1523:   await anim.finished.catch(() => {});
1524:   el.style.left = endX + 'px'; el.style.top = endY + 'px';
1525:   el.classList.add('ball-wobble');
1526:   await wait(950);
1527:   return { el, x: endX, y: endY };
1528: }
