for i,m in enumerate(d['messages']):
    if m.get('type')!='assistant': continue
    for c in m.get('content',[]):
        if c.get('type')=='tool' and c.get('name')=='read':
            inp=c.get('state',{}).get('input',{})
            path=inp.get('path','')
            if 'screenshots' not in path: continue
            cont=c.get('state',{}).get('content',[])
            for x in cont:
                if x.get('type')=='text' and x.get('text','').startswith('data:image'):
                    print('found inline',i,path)
                elif x.get('type')=='image':
                    print('image part',i,path,x.keys())
            # look metadata?
            meta=c.get('state',{}).get('metadata',{})
            if 'image' in meta: print('meta image',i,path)
            print(i,path,cont[:1])
